mapper.select:
/*selectCodeList*/ WITH mgmtCodeListPage AS( SELECT * FROM ( SELECT * FROM ( SELECT A.* ,ROWNUM AS RNUM FROM( SELECT COUNT(*) OVER() TOTALCNT ,CODE_SEQ ,CODE_ID ,CODE_NM ,CODE_VALUE ,CODE_DESC ,ACCESS_RIGHT ,PARENT_ID ,TO_NUMBER(SORT_ORDER) AS SORT_ORDER ,USE_FLAG ,DEFAULT_YN ,CREATE_USER ,CREATE_DATE ,MODIFY_USER ,MODIFY_DATE FROM TB_M_FINANCE_CONFIG
WHERE PARENT_ID IS NULL
WHERE PARENT_ID IS NOT NULL
AND PARENT_ID = #{sel_parentid}
AND CODE_NM = #{sel_codename}
AND USE_FLAG = #{sel_useyn}
ORDER BY TO_NUMBER(SORT_ORDER) ) A ) WHERE RNUM <= ${totalPagesize} ) WHERE RNUM > ${currentPageSize} ) SELECT * FROM mgmtCodeListPage

SELECT (CASE WHEN MAX(TO_NUMBER(SORT_ORDER)) > 0 THEN MAX(TO_NUMBER(SORT_ORDER)) ELSE TO_NUMBER(0) END) + 1 AS CODE_SEQ FROM TB_M_FINANCE_CONFIG WHERE 1=1
AND PARENT_ID IS NULL
AND PARENT_ID = #{parent_id}

mapper.insert:
	    INSERT INTO TB_M_FINANCE_CONFIG
    		(	 CODE_SEQ, CODE_ID, CODE_NM, CODE_VALUE, CODE_DESC
    			, ACCESS_RIGHT ,USE_FLAG,DEFAULT_YN, PARENT_ID, SORT_ORDER
    			, MODIFY_USER ,MODIFY_DATE  ,CREATE_USER ,CREATE_DATE
    		)VALUES(
    		 	(SELECT (CASE WHEN COUNT(*) = 0 THEN 1 ELSE  MAX(CODE_SEQ) + 1 END) AS CODE_SEQ 
                    FROM TB_M_FINANCE_CONFIG)
                  ,#{in_codeid}, #{in_codename}, #{in_codevalue}, #{in_codedesc}
    			  ,#{in_codeaccess} ,#{in_useyn},#{in_default}, #{in_codeparent},  #{in_sortorder}
    			  ,#{in_user_id} ,sysdate,#{in_user_id},sysdate
   			)

mapper.update:
UPDATE TB_M_FINANCE_CONFIG
   SET  CODE_ID = #{in_codeid} 
   	  ,CODE_NM = #{in_codename}
   	  ,CODE_VALUE = #{in_codevalue}
      ,CODE_DESC = #{in_codedesc}
      ,ACCESS_RIGHT = #{in_codeaccess}
      ,USE_FLAG = #{in_useyn}
      ,DEFAULT_YN = #{in_default}
      ,PARENT_ID = #{in_codeparent}
      ,SORT_ORDER = #{in_sortorder}
      ,MODIFY_USER = #{in_user_id}
      ,MODIFY_DATE = sysdate
WHERE CODE_SEQ = #{in_codeseq}

UPDATE TB_M_FINANCE_CONFIG
   SET SORT_ORDER = #{in_sortorder}
      ,MODIFY_USER = #{in_user_id}
      ,MODIFY_DATE = sysdate
WHERE CODE_SEQ = #{in_codeseq}
